// Some portions generated by Claude

// @ts-check
const { test, expect } = require('@playwright/test');
const {
	createSeededRepository,
	deleteRepository,
	openQueryPage,
	repositoryPageUrl,
	serverBaseUrl,
	setQueryEditor,
	uniqueRepositoryId,
	workbenchBaseUrl
} = require('./workbench-test-helpers.js');

const REPOSITORY_ID = uniqueRepositoryId('workbench-query-workflow');

test.describe.configure({ mode: 'serial' });

test.beforeAll(async ({ request }) => {
	await createSeededRepository(request, serverBaseUrl(), REPOSITORY_ID);
});

test.afterAll(async ({ request }) => {
	await deleteRepository(request, serverBaseUrl(), REPOSITORY_ID);
});

/** Records query execution POSTs and every request that leaves the Workbench origin. */
function recordRequests(page) {
	const workbenchOrigin = new URL(workbenchBaseUrl()).origin;
	const executions = [];
	const foreign = [];
	page.on('request', (request) => {
		const url = new URL(request.url());
		if (url.origin !== workbenchOrigin && !url.protocol.startsWith('data') && !url.protocol.startsWith('blob')) {
			foreign.push(request.url());
		}
		if (request.method() === 'POST' && url.pathname.endsWith(`/repositories/${REPOSITORY_ID}/query`)) {
			const body = new URLSearchParams(request.postData() || '');
			if (body.get('action') === 'exec') {
				executions.push(body);
			}
		}
	});
	return { executions, foreign };
}

test('Cmd/Ctrl+Enter in the query editor runs the query', async ({ page }) => {
	const requests = recordRequests(page);
	await openQueryPage(page, REPOSITORY_ID);
	await page.locator('.CodeMirror').first().click();
	await page.keyboard.press('ControlOrMeta+A');
	await page.keyboard.press('Backspace');
	await page.keyboard.type('ASK { ?s ?p ?o }');
	await page.keyboard.press('ControlOrMeta+Enter');
	await expect(page.locator('#query-results')).toContainText('Yes', { timeout: 15000 });
	expect(requests.executions).toHaveLength(1);
	expect(requests.executions[0].get('query')).toBe('ASK { ?s ?p ?o }');
	expect(requests.foreign).toEqual([]);
});

test('Cmd/Ctrl+Enter in the update editor executes the update', async ({ page }) => {
	await page.goto(repositoryPageUrl(REPOSITORY_ID, 'update'), { waitUntil: 'networkidle' });
	await page.locator('#update-editor .CodeMirror').waitFor();
	await page.locator('#update-editor .CodeMirror').click();
	await page.keyboard.press('ControlOrMeta+A');
	await page.keyboard.press('Backspace');
	await page.keyboard.type('INSERT DATA { <urn:a> <urn:b> <urn:c> }');
	await page.keyboard.press('ControlOrMeta+Enter');
	await expect(page).toHaveURL(new RegExp(`/repositories/${REPOSITORY_ID}/summary$`), { timeout: 15000 });
});

